import { withRetry } from "./util/retry.js";
import { HttpError } from "./util/errors.js";

export async function fetchOrder(client, id) {
  return withRetry(async () => {
    const res = await client.fetchImpl(`${client.baseUrl}/orders/${id}`);
    if (!res.ok) throw new HttpError("GET", `/orders/${id}`, res.status);
    return res.json();
  });
}

