export async function getUser(client, id) {
  let lastErr;
  for (let i = 0; i < 3; i++) {
    const res = await client.fetchImpl(`${client.baseUrl}/users/${id}`);
    if (res.ok) return res.json();
    lastErr = new Error(`GET /users/${id} failed: ${res.status}`);
    if (res.status < 500) break;
    await new Promise((r) => setTimeout(r, 100 * 2 ** i));
  }
  throw lastErr;
}

