import { test } from "node:test";
import assert from "node:assert/strict";
import { getUser } from "../src/users.js";

test("getUser retries a 503", async () => {
  let calls = 0;
  const fetchImpl = async () => {
    calls++;
    return calls === 1
      ? { ok: false, status: 503, json: async () => ({}) }
      : { ok: true, status: 200, json: async () => ({ id: 7 }) };
  };
  assert.deepEqual(await getUser({ baseUrl: "https://x", fetchImpl }, 7), { id: 7 });
});
